package remote

import (
	"context"
	"io"

	"google.golang.org/grpc"
)

// Locator identifies a capability's gRPC services as named by a peer.
//
// Target is a gRPC target string. LegacyHandle is the opaque numeric handle that
// was generated by go-hashicorp plugin.
// A [Transport] resolving a Locator should treat Target as
// authoritative when it is non-empty and fall back to LegacyHandle otherwise.
type Locator struct {
	Target       string
	LegacyHandle uint32
}

type Transport interface {
	Publish(name string, register func(*grpc.Server)) (Locator, io.Closer, error)
	// Dial returns a connection to the capability named by the Locator resolve
	// reports. A transport may resolve during the call or defer it to first use, so
	// resolve takes its own context and may be called more than once.
	Dial(ctx context.Context, name string, resolve func(context.Context) (Locator, error)) (ClientConn, error)
}
